fn first_word(s: &str) -> &str {
    match s.find(' ') {
        Some(i) => &s[..i],
        None => s,
    }
}

fn main() {
    let owned = String::from("quick brown fox");
    println!("{}", first_word(&owned));
    println!("{}", first_word("lazy dog"));
}

fn sum(numbers: &[i32]) -> i32 {
    let mut total = 0;
    for n in numbers {
        total += n;
    }
    total
}

fn main() {
    let all = [1, 2, 3, 4, 5];
    println!("{}", sum(&all));
    println!("{}", sum(&all[1..3]));
}

